import logging
import traceback
import random
import string

# Configure logging
logging.basicConfig(level=logging.ERROR)
logger = logging.getLogger(__name__)

class OrderService:
    def __init__(self, stock) -> None:
        """`stock` is a client for the remote inventory service. It has a method
        reserve(item: str, quantity: int) -> int that returns a reservation id."""
        self.stock = stock

    def _generate_error_code(self) -> str:
        """Generate a unique error reference code."""
        return ''.join(random.choices(string.ascii_uppercase + string.digits, k=8))

    def place_order(self, user: str, item: str, quantity: int, is_admin: bool = False) -> tuple[int, str]:
        """Handle an order request from the web page.
        Returns (HTTP status code, text shown to the user); on success (200, a confirmation text)."""
        try:
            # Validate inputs
            if not isinstance(user, str) or not user.strip():
                error_code = self._generate_error_code()
                logger.error(f"Invalid user input: '{user}' - Reference: {error_code}")
                return (400, f"Invalid user. Reference: {error_code}")

            if not isinstance(item, str) or not item.strip():
                error_code = self._generate_error_code()
                logger.error(f"Invalid item input: '{item}' - Reference: {error_code}")
                return (400, f"Invalid item. Reference: {error_code}")

            if not isinstance(quantity, int) or quantity <= 0:
                error_code = self._generate_error_code()
                logger.error(f"Invalid quantity: {quantity} - Reference: {error_code}")
                return (400, f"Invalid quantity. Reference: {error_code}")

            # Reserve the item in inventory
            reservation_id = self.stock.reserve(item, quantity)

            # Success case
            confirmation_text = f"Order placed successfully! Your reservation ID is {reservation_id}."
            return (200, confirmation_text)

        except Exception as e:
            # Handle unexpected errors
            error_code = self._generate_error_code()

            # Log the full error with traceback
            logger.error(f"Unexpected error during order placement for user '{user}', item '{item}', quantity {quantity}: {str(e)} - Reference: {error_code}", exc_info=True)

            # For regular users, show generic message without technical details
            if not is_admin:
                return (500, f"An error occurred while processing your order. Please try again later. Reference: {error_code}")
            else:
                # For admins, include some technical details (but not full traceback in response)
                return (500, f"Server error: {type(e).__name__} - {str(e)}. Reference: {error_code}")
